const item = $input.item.json;
const name = (item.researchCandidateName || '').toString().trim();
const now = new Date().toISOString();

// Technischer, einzelkandidat-bezogener Recherche-Adapter. Der Parent startet
// diese Child-Execution fire-and-forget und fuehrt den Fan-in ueber die
// Runtime-Data-Table aus. Es wird explizit keine echte Qlik-Analyse oder
// Websuche durchgefuehrt; jeder Wert bleibt klar als Dummy gekennzeichnet.
if (!name) {
  throw new Error('researchCandidateName fehlt - kein Kandidat fuer diese Recherche-Ausfuehrung uebergeben.');
}

const seed = name.length;
const researchResult = {
  candidate: name,
  club: `Dummy-Verein ${seed}`,
  contract: 'Simulierter Vertrag bis 30.06.2027 (keine echte Recherche)',
  marketValue: `${(5 + (seed % 5)).toFixed(1)} Mio. EUR (simuliert)`,
  injuries: 'Keine bekannten Verletzungen (simuliert, keine echte Recherche)',
  news: [`Simulierte Meldung zu ${name} (keine echte Websuche durchgefuehrt)`],
  source: 'Dummy-Quelle (keine echte Web-/Qlik-Recherche)',
  timestamp: now,
  confidence: 0.4,
  uncertain: false,
  uncertaintyReason: null
};

return [{ json: { ...item, researchResult } }];

const item = $input.item.json;
const now = new Date().toISOString();

return [{
  json: {
    ...item,
    researchRuntimeBatchId: item.researchBatchId,
    researchRuntimeCandidate: item.researchCandidateName,
    researchRuntimeStatus: 'success',
    researchRuntimePayload: JSON.stringify(item.researchResult),
    researchRuntimeCompletedAt: now
  }
}];

const input = $input.item.json || {};
const original = $('Wenn von anderem Workflow aufgerufen').first().json || {};
const batchId = input.researchBatchId || original.researchBatchId;
const candidate = input.researchCandidateName || original.researchCandidateName || 'unbekannter Kandidat';
const reason = (input.error && (input.error.message || input.error)) || 'Research-Zweig ist fehlgeschlagen.';
const now = new Date().toISOString();

const researchResult = {
  candidate,
  club: null,
  contract: null,
  marketValue: null,
  injuries: null,
  news: [],
  source: 'Recherche fehlgeschlagen (keine Quelle verfuegbar)',
  timestamp: now,
  confidence: 0,
  uncertain: true,
  uncertaintyReason: String(reason)
};

return [{
  json: {
    ...original,
    ...input,
    researchRuntimeBatchId: batchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: 'error',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];
